package com.campusconnect.service;
import com.campusconnect.dao.ComplaintDAO; import com.campusconnect.model.Complaint; import com.campusconnect.util.ValidationUtil; import java.util.*;
public class ComplaintService { private final ComplaintDAO dao=new ComplaintDAO(); public List<Complaint> forStudent(int id){return dao.findByStudent(id);} public List<Complaint> all(){return dao.findAll();} public void create(Complaint c){ValidationUtil.required(c.getCategory(),"Category");ValidationUtil.required(c.getDescription(),"Description");ValidationUtil.required(c.getPriority(),"Priority");dao.insert(c);} public void update(int id,String status,String priority,String remarks){ValidationUtil.required(status,"Status");ValidationUtil.required(priority,"Priority");dao.updateStatus(id,status,priority,remarks==null?"":remarks);} public void delete(int id){dao.delete(id);} public int pending(){return dao.countStatus("Pending");} public int resolved(){return dao.countStatus("Resolved");} }
